/// <summary>
/// Misc. event handlers related to picking list registration form
/// </summary>
class METPickingListRegistrationFormEventHandler
{
}

Method.Source:
/// </summary>
/// MPJ_24819_SOParametersAndCancelLinePickList
/// Control cancel picking route button
/// </summary>
/// <param name="args"></param>
[PostHandlerFor(formStr(WMSPickingRegistration), formMethodStr(WMSPickingRegistration, enableRouteFunctionsButton))]
public static void WMSPickingRegistration_Post_enableUpdateButtons(XppPrePostArgs args)
{  
    FormRun         metFormRunStd = args.getThis();
    if(METCustParameters::find().DisablePickListCancel)
    {
        
        WMSPickingRoute metWMSPickingRouteStd = metFormRunStd.dataHelper().FindDataSource(formDataSourceStr(WMSPickingRegistration, WMSPickingRoute)).cursor();;
        SalesLine       metSalesLineStd;
        METSalesLine    metSalesLine;
        boolean         setEnable;
        select firstonly OrderExtractStatus from metSalesLine
            exists join metSalesLineStd
            where metSalesLineStd.RecId == metSalesLine.SalesLine &&
            metSalesLineStd.SalesId              == metWMSPickingRouteStd.transRefId &&
                  metWMSPickingRouteStd.transType       == InventTransType::Sales &&
            metSalesLine.OrderExtractStatus    == METOrderExtractStatus::Extracted;
        if(metSalesLine.OrderExtractStatus)
        {
            setEnable=false;
        }
        else
        {
            setEnable=true;
        }
        metFormRunStd.design().controlName('WMSPickingRouteCancel').enabled(setEnable);
    }        
        
}
